import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ onChange }: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>([]);

  const updateTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const removeTag = (tag: string) => {
    updateTags(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={updateTags}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

